function registryIndex(registryRows, diagnostics = []) {
  const map = new Map();
  registryRows.forEach((item, index) => {
    if (!item || typeof item !== 'object' || Array.isArray(item)) {
      diagnostics.push({
        code: 'malformed_registry_row',
        row_index: index,
        reason: 'row_is_not_an_object',
        severity: 'critical',
      });
      return;
    }
    if (item.document_kind !== 'question_paper') return;
    if (!item.source_pdf_path || !item.source_document_id) {
      diagnostics.push({
        code: 'malformed_registry_row',
        row_index: index,
        reason: 'required_fields_missing',
        severity: 'critical',
      });
      return;
    }
    const key = item.source_pdf_path;
    if (!map.has(key)) {
      map.set(key, {
        path: DEFAULT_PATHS.sourceDocumentRegistry,
        json_pointer: '/registry/' + index,
        source_document_id: item.source_document_id,
        source_review_status: item.source_review_status,
        source_pdf_path: item.source_pdf_path,
      });
    }
  });
  return map;
}

function cropRiskIndex(cropRows, diagnostics = []) {
  const map = new Map();
  cropRows.forEach((item, index) => {
    if (!item || typeof item !== 'object' || Array.isArray(item)) {
      diagnostics.push({
        code: 'malformed_crop_risk_row',
        row_index: index,
        reason: 'row_is_not_an_object',
        severity: 'critical',
      });
      return;
    }
    const sourcePdf = item.source_document_ref?.source_pdf_path;
    const qNumber = String(item.question_image_id ?? '').replace(/^q/iu, '');
    if (!sourcePdf || !qNumber) {
      diagnostics.push({
        code: 'malformed_crop_risk_row',
        row_index: index,
        reason: 'required_fields_missing',
        severity: 'critical',
      });
      return;
    }
    const key = sourceDocumentKey(sourcePdf, qNumber);
    if (!key) {
      diagnostics.push({
        code: 'malformed_crop_risk_row',
        row_index: index,
        reason: 'failed_to_construct_key',
        severity: 'critical',
      });
      return;
    }
    if (!map.has(key)) {
      map.set(key, {
        path: DEFAULT_PATHS.historicalCropRiskAudit,
        json_pointer: '/rows/' + index,
        crop_path: item.crop_path,
        student_display_eligible: item.student_display_eligible === true,
        quality_status: item.quality_status,
      });
    }
  });
  return map;
}
